export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"identifying-dialectics-for-each-group-check-the-most-dialectical-response-e0d5be1485d5\",\"title\":\"Identifying Dialectics For each group, check the most dialectical response. \uf8f1\u2022 \uf8f4\u2022\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9715],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/03-dbt-interpersonal-effectiveness-interpersonal-effectiveness-handout-16c-identifying-diale-f64d425a45.json\",\"sha256\":\"f64d425a4540eb5d6b65ec13416d86a0692db9e341e8a6f9c2ba13e12c9bfec5\",\"domain\":\"dbt\",\"bytes\":6629},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/interpersonal-effectiveness-handout-16c-identifying-dialectics-for-each-group-check-the-most-c8204a7674.json\",\"sha256\":\"c8204a7674eb2126fb74cb95c0ee664d25eb6d2f2e38f6cbb64a2d01c9979dfe\",\"domain\":\"dbt\",\"bytes\":6460}]},\"data\":{\"pages\":[{\"pdf_page\":178,\"book_page\":\"154\",\"text\":\"154\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nInterpersonal Effectiveness Handout 16c\\nIdentifying Dialectics\\nFor each group, check the most dialectical response.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 1A.\\tPay attention to your effect on others.\\n\\u0003\\n\u0089 1B.\\tAssume that others\u2019 reactions to you\\nare unrelated to your treatment of\\nthem.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 5A.\\tExamine a difficult relationship by\\nlooking at how the interactions over\\ntime between you and the other\\nperson may be problematic.\\n\\u0003\\n\u0089 5B.\\tAssume that difficulties in a\\nrelationship are caused completely by\\nyou or by the other person.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 2A.\\t\u201cI know I am right about this.\u201d\\n\\u0003\\n\u0089 2B.\\t\u201cI can see your point of view, even\\nthough I do not agree with it.\u201d\\n\\u0003\\n\u0089 2C.\\t\u201cThe way you are thinking doesn\u2019t\\nmake any sense.\u201d\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 6A.\\t\u201cIt is hopeless. I cannot do it.\u201d\\n\\u0003\\n\u0089 6B.\\t\u201cThis is a breeze. I\u2019ve got no\\nproblems.\u201d\\n\\u0003\\n\u0089 6C.\\t\u201cThis is really hard for me, and I am\\ngoing to keep trying.\u201d\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 3A.\\t\u201cEveryone always treats me unfairly.\u201d\\n\\u0003\\n\u0089 3B.\\t\u201cI believe the coach should reconsider\\nhis decision to cut me from the team.\u201d\\n\\u0003\\n\u0089 3C.\\t\u201cCoaches know best who to keep on\\nteams and who to cut.\u201d\\n\uf8f1\u2022\uf8f4\u2022\uf8f4\u2022\uf8f4\u2022\uf8f2\u2022\uf8f4\u2022\uf8f4\u2022\uf8f4\u2022\uf8f3\\n\\u0003\\n\u0089 7A.\\tWhen you disagree with someone,\\nbe sure and be very clear about your\\npoint of view.\\n\\u0003\\n\u0089 7B.\\tWhen you disagree with someone, try\\nand see their point of view.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 4A.\\tJudge friends as disloyal and uncaring\\nif they start changing in ways you don\u2019t\\nlike.\\n\\u0003\\n\u0089 4B.\\tAccept that interests change.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 8A.\\tDemand that relationships be stable\\nwithout changing.\\n\\u0003\\n\u0089 8B.\\tEmbrace change and see it as\\ninevitable.\\nNote. Adapted in part from Miller, A. L., Rathus, J. H., & Linehan, M. M. (2007). Dialectical behavior therapy with suicidal adolescents. New York:\\nGuilford Press. Copyright 2007 by The Guilford Press. Adapted by permission.\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Interpersonal Effectiveness Handout 16c\",\"source_pdf_pages\":[178],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/interpersonal_effectiveness/handouts/interpersonal_effectiveness_handout_16c_identifying_dialectics_for_each_group_check_the_most_dialectical_respo.json\",\"item_number\":\"16c\",\"full_text\":\"Interpersonal Effectiveness Handout 16c\\nIdentifying Dialectics\\nFor each group, check the most dialectical response.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 1A.\\tPay attention to your effect on others.\\n\\u0003\\n\u0089 1B.\\tAssume that others\u2019 reactions to you\\nare unrelated to your treatment of\\nthem.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 5A.\\tExamine a difficult relationship by\\nlooking at how the interactions over\\ntime between you and the other\\nperson may be problematic.\\n\\u0003\\n\u0089 5B.\\tAssume that difficulties in a\\nrelationship are caused completely by\\nyou or by the other person.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 2A.\\t\u201cI know I am right about this.\u201d\\n\\u0003\\n\u0089 2B.\\t\u201cI can see your point of view, even\\nthough I do not agree with it.\u201d\\n\\u0003\\n\u0089 2C.\\t\u201cThe way you are thinking doesn\u2019t\\nmake any sense.\u201d\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 6A.\\t\u201cIt is hopeless. I cannot do it.\u201d\\n\\u0003\\n\u0089 6B.\\t\u201cThis is a breeze. I\u2019ve got no\\nproblems.\u201d\\n\\u0003\\n\u0089 6C.\\t\u201cThis is really hard for me, and I am\\ngoing to keep trying.\u201d\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\nSaying:\\n\\u0003\\n\u0089 3A.\\t\u201cEveryone always treats me unfairly.\u201d\\n\\u0003\\n\u0089 3B.\\t\u201cI believe the coach should reconsider\\nhis decision to cut me from the team.\u201d\\n\\u0003\\n\u0089 3C.\\t\u201cCoaches know best who to keep on\\nteams and who to cut.\u201d\\n\uf8f1\u2022\uf8f4\u2022\uf8f4\u2022\uf8f4\u2022\uf8f2\u2022\uf8f4\u2022\uf8f4\u2022\uf8f4\u2022\uf8f3\\n\\u0003\\n\u0089 7A.\\tWhen you disagree with someone,\\nbe sure and be very clear about your\\npoint of view.\\n\\u0003\\n\u0089 7B.\\tWhen you disagree with someone, try\\nand see their point of view.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 4A.\\tJudge friends as disloyal and uncaring\\nif they start changing in ways you don\u2019t\\nlike.\\n\\u0003\\n\u0089 4B.\\tAccept that interests change.\\n\uf8f1\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f2\u2022\\n\uf8f4\u2022\\n\uf8f4\u2022\\n\uf8f3\\n\\u0003\\n\u0089 8A.\\tDemand that relationships be stable\\nwithout changing.\\n\\u0003\\n\u0089 8B.\\tEmbrace change and see it as\\ninevitable.\\nNote. Adapted in part from Miller, A. L., Rathus, J. H., & Linehan, M. M. (2007). Dialectical behavior therapy with suicidal adolescents. New York:\\nGuilford Press. Copyright 2007 by The Guilford Press. Adapted by permission.\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[],\"id\":\"interpersonal_effectiveness_handout_16c\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"154\"],\"title\":\"Identifying Dialectics For each group, check the most dialectical response. \uf8f1\u2022 \uf8f4\u2022\",\"module_category\":\"Interpersonal Effectiveness Skills\",\"shared_json_path\":\"shared/03_dbt_interpersonal_effectiveness/handouts_json/interpersonal_effectiveness_handout_16c_identifying_dialectics_for_each_g_6e2cbffa.json\",\"module\":\"Interpersonal Effectiveness\",\"keywords\":[\"Dialectics\",\"Identifying\",\"check\",\"dialectical\",\"each\",\"group\",\"most\",\"response\"]}}");
